struct Matrix<T> {
    data: Vec<Vec<T>>,
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns

    // Create a new matrix with the specified shape
    let mut matrix = Matrix {
        data: vec![vec![0; c]; r],
    };

    if r == a.len() {
        // Treat `a` as a column vector
        for i in 0..r {
            matrix.data[i] = a.clone(); // Copy the entire array to each row
        }
    } else {
        // Treat `a` as a row vector
        for i in 0..r {
            for j in 0..c {
                matrix.data[i][j] = a[j]; // Fill each row with elements from `a`
            }
        }
    }

    matrix
}

fn main() {
    let a = vec![1, 2, 3];
    let shape = vec![3, 2];
    let result = broadcast(a, shape);

    for row in result.data {
        println!("{:?}", row);
    }
}